-- Generated by tools/seed/build_drop_seed.py from the "Eorzea 1.x Loot Ledger" artifact.
-- DO NOT EDIT BY HAND - re-run the generator. Rules:
-- Rates are per 10000. groupId 0 = independent roll; groupId N = one roll at groupRate,
-- then one row picked weighted by rate. dropListId = spawn groupId.

CREATE TABLE IF NOT EXISTS `server_battlenpc_drop_list` (
  `dropListId` int(10) unsigned NOT NULL,
  `groupId` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `groupRate` smallint(5) unsigned NOT NULL DEFAULT 0,
  `itemId` int(10) unsigned NOT NULL,
  `rate` smallint(5) unsigned NOT NULL,
  `minQty` int(10) unsigned NOT NULL DEFAULT 1,
  `maxQty` int(10) unsigned NOT NULL DEFAULT 1,
  `hqRate` smallint(5) unsigned NOT NULL DEFAULT 0,
  `quality` tinyint(3) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`dropListId`,`groupId`,`itemId`,`quality`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `server_battlenpc_drop_list` WHERE `dropListId` BETWEEN 100001 AND 199999;
UPDATE `server_battlenpc_groups` SET `dropListId` = 0 WHERE `groupId` BETWEEN 100001 AND 199999;

